import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import styles from './Spinner.module.css';

type SpinnerSize = 'inherit' | 'xs' | 'sm' | 'md' | 'lg' | 'xl';

type SpinnerRootProps = HTMLArkProps<'span'> & {
  size?: SpinnerSize;
  decorative?: boolean;
};

function Spinner(props: SpinnerRootProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'children',
    'class',
    'decorative',
    'aria-label',
    'size',
  ]);

  return (
    <ark.span
      asChild={local.asChild}
      {...others}
      data-scope="spinner"
      data-part="root"
      data-slot="spinner-root"
      data-size={local.size ?? 'md'}
      role={local.decorative ? undefined : 'status'}
      aria-hidden={local.decorative || undefined}
      aria-label={
        local['aria-label'] ??
        (local.decorative || others['aria-labelledby'] ? undefined : a11yLabels.loading)
      }
      class={clsx(styles.root, local.class)}
    >
      <span
        data-scope="spinner"
        data-part="indicator"
        data-slot="spinner-indicator"
        class={styles.indicator}
        aria-hidden="true"
      >
        {local.children ?? (
          <span
            data-scope="spinner"
            data-part="ring"
            data-slot="spinner-ring"
            class={styles.ring}
          />
        )}
      </span>
    </ark.span>
  );
}

export { Spinner };
export type { SpinnerRootProps, SpinnerSize };

@layer moduix.components {
  .root {
    --_spinner-size: var(--moduix-spacing-5);

    display: inline-flex;
    width: var(--moduix-spinner-size, var(--_spinner-size));
    height: var(--moduix-spinner-size, var(--_spinner-size));
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    vertical-align: middle;

    &[data-size='xs'] {
      --_spinner-size: var(--moduix-spacing-3);
    }

    &[data-size='sm'] {
      --_spinner-size: var(--moduix-spacing-4);
    }

    &[data-size='lg'] {
      --_spinner-size: var(--moduix-spacing-7);
    }

    &[data-size='xl'] {
      --_spinner-size: var(--moduix-size-md);
    }

    &[data-size='inherit'] {
      width: 1em;
      height: 1em;
    }
  }

  .indicator,
  [data-scope='spinner'][data-part='indicator'] {
    display: inline-flex;
    width: 100%;
    height: 100%;
    align-items: center;
    justify-content: center;
    animation: var(--moduix-animation-spin);

    & :where(svg) {
      width: 100%;
      height: 100%;
    }
  }

  .ring,
  [data-scope='spinner'][data-part='ring'] {
    box-sizing: border-box;
    display: block;
    width: 100%;
    height: 100%;
    border: var(--moduix-spinner-ring-border-width, var(--moduix-border-width-md)) solid
      var(--moduix-spinner-ring-track-color, color-mix(in oklab, currentColor 22%, transparent));
    border-block-start-color: currentColor;
    border-radius: var(--moduix-radius-full);
  }
}
